    """Refuse a non-loopback bind; the preview is a local developer tool only."""
    try:
        from streamlit import runtime
        from streamlit.web.server import server_util
    except Exception:  # noqa: BLE001 - Streamlit is optional and unverified here
        return
    context = runtime.get_script_run_ctx()
    if context is None:
        return
    session = getattr(context, "session_id", None)
    del session
    configured = server_util.get_url("/")
    del configured


